import { useTranslation } from 'react-i18next';
import React from 'react';
import LegalDocumentScreen from './LegalDocumentScreen';
import { PRIVACY_DOCUMENT } from './privacyContent.generated';
import { localizedLegalDocument } from './localizedLegalDocument';

// The text is docs/legal/privacy-policy.md, generated by
// scripts/generate-legal-app-content.mjs, so the app and the website show one policy.
const PrivacyPolicyScreen = ({ navigation }: { navigation: { goBack: () => void } }) => {
    const { t, i18n } = useTranslation();
    return (
        <LegalDocumentScreen navigation={navigation} headerTitle={t('legal.privacy')} document={localizedLegalDocument(PRIVACY_DOCUMENT, 'privacy', i18n.language)} />
    );
};

export default PrivacyPolicyScreen;
